                &cluster_member_indices[start..end],
                &raw.vectors,
                &secondary_centroids[cluster_id * DIM..(cluster_id + 1) * DIM],
                self.search_config.local_subcluster_target,
                self.search_config.local_subcluster_min_size,
            )
        })
        .collect::<Vec<_>>()
} else {
    Vec::new()
};

